import { runEndpoint } from "../lib/runEndpoint.js";

type Input = {
    /** SaaSFlow company id (UUID). Omit to use the currently active company. */
    companyId?: string;
    /** Metrics to return definitions for. Omit for all metrics, which needs both subscriptions:read and financials:read; name only subscription metrics (MRR, churn, retention) and subscriptions:read is enough. Comma-separated. */
    metricNames?: string;
    /** MRR variant. cmrr = committed MRR (CMRR), mrr = recognised MRR. */
    mrrType?: "cmrr" | "mrr";
};

export default async function dataMetricDefinitions(input: Input): Promise<Record<string, unknown>> {
    const { companyId, metricNames, mrrType } = input;

    return runEndpoint({
        method: "POST",
        pathTemplate: "/companies/{companyId}/data/metricDefinitions",
        companyId,
        body: {
            metricNames:
                metricNames === undefined
                    ? undefined
                    : metricNames
                          .split(",")
                          .map((s) => s.trim())
                          .filter(Boolean),
            mrrType,
        },
    });
}
